let tarefas = [];
let proximoCodigo = 1;
let filtroAtual = "todas";

const formulario = document.getElementById("formTarefa");
const titulo = document.getElementById("titulo");
const prioridade = document.getElementById("prioridade");
const lista = document.getElementById("listaTarefas");
const mensagem = document.getElementById("mensagem");

function cadastrarTarefa(nome, nivel) {
    if (!nome || nome.trim().length < 5) {
            return {
                        sucesso: false,
                                    texto: "Digite pelo menos 5 caracteres."
                                            };
                                                }

                                                    const p = Number(nivel);

                                                        if (![1, 2, 3].includes(p)) {
                                                                return {
                                                                            sucesso: false,
                                                                                        texto: "Escolha uma prioridade válida."
                                                                                                };
                                                                                                    }

                                                                                                        tarefas.push({
                                                                                                                codigo: proximoCodigo++,
                                                                                                                        titulo: nome.trim(),
                                                                                                                                prioridade: p,
                                                                                                                                        concluida: false
                                                                                                                                            });

                                                                                                                                                return {
                                                                                                                                                        sucesso: true,
                                                                                                                                                                texto: "Tarefa criada com sucesso!"
                                                                                                                                                                    };
                                                                                                                                                                    }

                                                                                                                                                                    function alternarTarefa(codigo) {
                                                                                                                                                                        const tarefa = tarefas.find(t => t.codigo === codigo);

                                                                                                                                                                            if (tarefa) {
                                                                                                                                                                                    tarefa.concluida = !tarefa.concluida;
                                                                                                                                                                                            atualizarTela();
                                                                                                                                                                                                }
                                                                                                                                                                                                }

                                                                                                                                                                                                function removerTarefa(codigo) {
                                                                                                                                                                                                    tarefas = tarefas.filter(t => t.codigo !== codigo);
                                                                                                                                                                                                        atualizarTela();
                                                                                                                                                                                                        }

                                                                                                                                                                                                        function definirFiltro(filtro) {
                                                                                                                                                                                                            filtroAtual = filtro;
                                                                                                                                                                                                                atualizarTela();
                                                                                                                                                                                                                }

                                                                                                                                                                                                                function criarElemento(tag, classe, texto) {
                                                                                                                                                                                                                    const elemento = document.createElement(tag);
                                                                                                                                                                                                                        elemento.className = classe;
                                                                                                                                                                                                                            elemento.textContent = texto;
                                                                                                                                                                                                                                return elemento;
                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                function atualizarTela() {
                                                                                                                                                                                                                                    document.getElementById("total").textContent =
                                                                                                                                                                                                                                            tarefas.length;

                                                                                                                                                                                                                                                document.getElementById("pendentes").textContent =
                                                                                                                                                                                                                                                        tarefas.filter(t => !t.concluida).length;

                                                                                                                                                                                                                                                            document.getElementById("concluidas").textContent =
                                                                                                                                                                                                                                                                    tarefas.filter(t => t.concluida).length;

                                                                                                                                                                                                                                                                        const filtradas = tarefas.filter(t => {
                                                                                                                                                                                                                                                                                if (filtroAtual === "pendentes") return !t.concluida;
                                                                                                                                                                                                                                                                                        if (filtroAtual === "concluidas") return t.concluida;
                                                                                                                                                                                                                                                                                                return true;
                                                                                                                                                                                                                                                                                                    });

                                                                                                                                                                                                                                                                                                        lista.innerHTML = "";

                                                                                                                                                                                                                                                                                                            const nomeFiltro = {
                                                                                                                                                                                                                                                                                                                    todas: "Todas",
                                                                                                                                                                                                                                                                                                                            pendentes: "Pendentes",
                                                                                                                                                                                                                                                                                                                                    concluidas: "Concluídas"
                                                                                                                                                                                                                                                                                                                                        };

                                                                                                                                                                                                                                                                                                                                            document.getElementById("mostrarTodas").textContent =
                                                                                                                                                                                                                                                                                                                                                    nomeFiltro[filtroAtual];

                                                                                                                                                                                                                                                                                                                                                        if (filtradas.length === 0) {
                                                                                                                                                                                                                                                                                                                                                                const vazio = document.createElement("div");
                                                                                                                                                                                                                                                                                                                                                                        vazio.className = "vazio";

                                                                                                                                                                                                                                                                                                                                                                                const icone = criarElemento("div", "desenho", "✓");
                                                                                                                                                                                                                                                                                                                                                                                        const tituloVazio = criarElemento(
                                                                                                                                                                                                                                                                                                                                                                                                    "h3",
                                                                                                                                                                                                                                                                                                                                                                                                                "",
                                                                                                                                                                                                                                                                                                                                                                                                                            filtroAtual === "todas"
                                                                                                                                                                                                                                                                                                                                                                                                                                            ? "Tudo começa com uma tarefa!"
                                                                                                                                                                                                                                                                                                                                                                                                                                                            : "Nenhuma tarefa nesta categoria."
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const descricao = criarElemento(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        "p",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    "",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                "Suas atividades aparecerão aqui."
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                vazio.append(icone, tituloVazio, descricao);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        lista.appendChild(vazio);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        filtradas.forEach(tarefa => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const item = document.createElement("div");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        item.className = "tarefa";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const check = document.createElement("input");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        check.type = "checkbox";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                check.className = "check";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        check.checked = tarefa.concluida;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                check.setAttribute("aria-label", "Concluir tarefa");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        check.addEventListener("change", () => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    alternarTarefa(tarefa.codigo);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const info = document.createElement("div");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            info.className = "info";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (tarefa.concluida) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                info.classList.add("concluida");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const nome = criarElemento("h4", "", tarefa.titulo);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const codigo = criarElemento(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    "small",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                "",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            `Código #${tarefa.codigo}`
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            info.append(nome, codigo);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const nomes = {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                1: { texto: "Alta", classe: "alta" },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            2: { texto: "Média", classe: "media" },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        3: { texto: "Baixa", classe: "baixa" }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                };

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const dados = nomes[tarefa.prioridade];

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const etiqueta = criarElemento(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            "span",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        `prioridade ${dados.classe}`,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    dados.texto
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const excluir = criarElemento("button", "excluir", "Excluir");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            excluir.setAttribute("aria-label", `Excluir ${tarefa.titulo}`);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    excluir.addEventListener("click", () => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                removerTarefa(tarefa.codigo);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                item.append(check, info, etiqueta, excluir);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        lista.appendChild(item);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            formulario.addEventListener("submit", evento => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                evento.preventDefault();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const resultado = cadastrarTarefa(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            titulo.value,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    prioridade.value
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            mensagem.textContent = resultado.texto;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                mensagem.style.color = resultado.sucesso
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ? "#27864c"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                : "#bd5252";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (resultado.sucesso) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            formulario.reset();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    prioridade.value = "2";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            atualizarTela();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    titulo.focus();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        document.getElementById("verPendentes").addEventListener(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            "click",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                () => definirFiltro("pendentes")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                document.getElementById("verConcluidas").addEventListener(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    "click",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        () => definirFiltro("concluidas")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        document.getElementById("mostrarTodas").addEventListener(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            "click",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                () => definirFiltro("todas")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                document.querySelectorAll(".menu").forEach(botao => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    botao.addEventListener("click", () => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            document.querySelectorAll(".menu").forEach(menu => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        menu.classList.remove("ativo");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        botao.classList.add("ativo");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            atualizarTela();